    const apiOptions = params.ctx?.axiosInstance
      ? { _axiosInstance: params.ctx.axiosInstance }
      : undefined;
    const response = await ipnsControllerPublishRecord(
      {
        ipnsName: params.ipnsName,
        record: recordBase64,
